#include <stdio.h>
#include <stdlib.h>
#include <limits.h>
#include <errno.h>
#include <stdbool.h>

static bool parse_long(const char *s, long long *out)
{
    char *endptr = NULL;
    errno = 0;
    long long v = strtoll(s, &endptr, 10);
    if (errno != 0 || endptr == s || *endptr != '\0')
        return false;
    *out = v;
    return true;
}

static bool safe_abs(long long v, long long *abs_out)
{
    if (v == LLONG_MIN)
        return false;
    *abs_out = (v < 0) ? -v : v;
    return true;
}

static long long gcd_ll(long long a, long long b)
{
    while (b != 0) {
        long long r = a % b;
        a = b;
        b = r;
    }
    return a;
}

static bool lcm_overflows(long long a, long long b, long long g)
{
    long long part = a / g;
    if (part == 0)
        return false;
    return part > LLONG_MAX / b;
}

int main(int argc, char *argv[])
{
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }

    long long a, b;
    if (!parse_long(argv[1], &a) || !parse_long(argv[2], &b)) {
        puts("BAD_INPUT");
        return 0;
    }

    long long abs_a, abs_b;
    if (!safe_abs(a, &abs_a) || !safe_abs(b, &abs_b)) {
        puts("OVERFLOW");
        return 0;
    }

    if (abs_a > 1000000LL || abs_b > 1000000LL) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    if (abs_a == 0 && abs_b == 0) {
        puts("gcd=0 lcm=0");
        return 0;
    }

    long long g = gcd_ll(abs_a, abs_b);
    if (g == 0) {
        puts("gcd=0 lcm=0");
        return 0;
    }

    if (lcm_overflows(abs_a, abs_b, g)) {
        puts("OVERFLOW");
        return 0;
    }

    long long l = (abs_a / g) * abs_b;
    printf("gcd=%lld lcm=%lld\n", g, l);
    return 0;
}
